ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    codeResponse: "200",
    messageResponse: "consulta realizada exitosamente",
    utilitys: {
        operators: payload map (item) -> {
            code: item.Codigo,
            operator: upper(item.Operador),
            nrn: item.NRN
        }
    }
}

%dw 2.0
import * from dw::core::Dates
output application/json

// Fecha actual
var today = now() as Date

// Último día del año actual
var endOfYear = ((today.year as String) ++ "-12-31") as Date {format: "yyyy-MM-dd"}

// Extraer los festivos activos del payload en formato "yyyy-MM-dd"
var holidays =
    payload
        filter ((item) -> item.activo == true)
        map ((item) ->
            (item.dia_festivo as DateTime {format: "yyyy-MM-dd'T'HH:mm:ssXXX"})
                as String {format: "yyyy-MM-dd"}
        )

// Generar rango de fechas día a día
fun buildDays(start: Date, end: Date, acc = []) =
    if (start > end) acc
    else buildDays(start + |P1D|, end, acc ++ [start])

var allDays = buildDays(today, endOfYear)

// Filtrar solo lunes a viernes y excluir los festivos
var businessDays =
    allDays
        filter ((d) ->
            d.dayOfWeek >= 1 and d.dayOfWeek <= 5 and
            !(holidays contains (d as String {format: "yyyy-MM-dd"}))
        )
        map ((d) -> {
            date: (d as String {format: "yyyy-MM-dd"}) ++ "T00:00:00",
            day: d.day as String,
            month: d.month as String,
            monthNameShort: ["Ene","Feb","Mar","Abr","May","Jun","Jul","Ago","Sep","Oct","Nov","Dic"][d.month - 1],
            year: d.year as String
        })

---
{
    codeResponse: "200",
    messageResponse: "Consulta realizada exitosamente",
    businessDays: businessDays
}

%dw 2.0
output application/json
---
{
	codeResponse: "200",
	messageResponse: "Consulta realizada exitosamente",
	utilitys: {
		cancellationReasons: payload.result map (reason) -> {
			code: reason.Codigo,
			name: reason.Motivo,
			'default': reason.PorDefecto,
			applicableToPF: reason.Aplica_PF,
			steps: (reason.Pasos default []) map (step) -> step.Paso,
			subReasons: (reason.Submotivos default []) map (subReason) -> {
				code: subReason.Codigo,
				name: subReason.Submotivo,
				'default': subReason.PorDefecto
			}
		}
	}
}

%dw 2.0
output application/json
var profile = upper((Mule::p('pagination.profile') default "Bajo") as String)
var maxLimit = if (profile == "ALTO") ((Mule::p('pagination.profiles.alto.max') default 100) as Number) else if (profile == "MEDIO") ((Mule::p('pagination.profiles.medio.max') default 50) as Number) else ((Mule::p('pagination.profiles.bajo.max') default 25) as Number)
var defaultLimit = maxLimit
var defaultOffset = (Mule::p('pagination.default.offset') default 0) as Number
var reqLimit = (vars.parameters.limit default defaultLimit) as Number
var reqOffset = (vars.parameters.offset default defaultOffset) as Number
var limit = if (reqLimit > maxLimit) maxLimit else if (reqLimit < 0) 0 else reqLimit
var offset = if (reqOffset < 0) 0 else reqOffset
var utilitys = payload.utilitys default {}
var parameters = utilitys.parameters default []
var parametersLastIndex = sizeOf(parameters) - 1
var parametersToIndex = min([offset + limit - 1, parametersLastIndex])
var operators = utilitys.operators default []
var operatorsLastIndex = sizeOf(operators) - 1
var operatorsToIndex = min([offset + limit - 1, operatorsLastIndex])
var businessDays = payload.businessDays default []
var businessDaysLastIndex = sizeOf(businessDays) - 1
var businessDaysToIndex = min([offset + limit - 1, businessDaysLastIndex])
---
if ((utilitys.parameters default null) != null)
    ((payload - "utilitys")
        ++ {
          utilitys: utilitys ++ {
            parameters: if (sizeOf(parameters) == 0 or offset > parametersLastIndex) [] else parameters[offset to parametersToIndex]
          }
        })
else if ((utilitys.operators default null) != null)
    ((payload - "utilitys")
        ++ {
          utilitys: utilitys ++ {
            operators: if (sizeOf(operators) == 0 or offset > operatorsLastIndex) [] else operators[offset to operatorsToIndex]
          }
        })
else if ((payload.businessDays default null) != null)
    ((payload - "businessDays")
        ++ {
          businessDays: if (sizeOf(businessDays) == 0 or offset > businessDaysLastIndex) [] else businessDays[offset to businessDaysToIndex]
        })
else
    payload

ee:variables.ee:set-variable:
%dw 2.0
fun getPqrParams(filters) =
  filters splitBy ";" reduce ((item, acc = {}) -> acc ++ {
      ((item splitBy ":")[0]): ((item splitBy ":")[1])
    }) mapObject ((value, key, index) -> {
    (actividad: value) if (key as String == 'activity'),
    (grupo_gestion: value) if (key as String == 'managementGroup'),
    (clase: value) if (key as String == 'class'),
    (motivo: value) if (key as String == 'reason')
  })
output application/json  
---
getPqrParams(vars.parameters.FILTERS)

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	basePath: p("mongoDbSapi.basePath"),
	host: p("mongoDbSapi.host"),
	port: p("mongoDbSapi.port"),
	method: p('mongoDbSapi.dynamicQuery.post.method'),
	path: p('mongoDbSapi.dynamicQuery.path'),
	body: {
		"query": {
			"aggregate": "PQR_ACTIVIDAD",
			"pipeline": [
				{
					"\$match": vars.filtersPqr ++ { estado: "ACTIVO"}
				},
				({
					"\$skip": vars.parameters.OFFSET as Number
				}) if (!isEmpty(vars.parameters.OFFSET)),
  				({
					"\$limit": vars.parameters.LIMIT as Number
				}) if (!isEmpty(vars.parameters.LIMIT))

			],
			"cursor": {
			}
		}
	},
	headers: {
		"client_secret": p('secure::api.clientSecret'),
		"client_id": p('secure::api.clientId'),
		"name": vars.headers.name,
		"X-CORRELATION-ID": vars.headers."x-correlation-id",
		"source": vars.headers.source,
		"systemId": vars.headers.systemId
	},
	queryParameters: {
	},
	uriParameters: {
	}
}
